#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<vector<long long>> mt(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> mt[i][j];
        }
    }

    sort(mt.begin(), mt.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[1] < y[1]; });
    multiset<long long> rooms;
    for (long long i = 0; i < k; i++) rooms.insert(0);
    long long count = 0;
    for (const vector<long long>& m : mt) {
        auto it = rooms.upper_bound(m[0]);
        if (it != rooms.begin()) {
            --it;
            rooms.erase(it);
            rooms.insert(m[1]);
            count++;
        }
    }
    cout << count << "\n";

    return 0;
}

