import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[][] mt = new long[(int) n][2];
        for (int i = 0; i < mt.length; i++) {
            for (int j = 0; j < mt[i].length; j++) {
                mt[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n, ck = (int) k;
        long[] keys = new long[cn];
        for (int i = 0; i < cn; i++) keys[i] = (mt[i][1] << 15) | i;
        Arrays.sort(keys);
        long[] rooms = new long[ck];
        long count = 0;
        for (int t = 0; t < cn; t++) {
            int id = (int) (keys[t] & 32767L);
            long s = mt[id][0], e = mt[id][1];
            int lo = 0, hi = ck;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (rooms[mid] <= s) lo = mid + 1;
                else hi = mid;
            }
            int i = lo - 1;
            if (i >= 0) {
                for (int j = i; j + 1 < ck; j++) rooms[j] = rooms[j + 1];
                int p = ck - 1;
                while (p > 0 && rooms[p - 1] > e) {
                    rooms[p] = rooms[p - 1];
                    p--;
                }
                rooms[p] = e;
                count++;
            }
        }
        System.out.println(count);
    }
}
